package io.knowledgebrain.learning;
import java.util.*;import java.io.IOException;import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.MeterRegistry;
@RestController @ConditionalOnProperty(name="brain.learning.public.enabled",havingValue="true")
@RequestMapping("/api/public/spaces/{spaceId}")
final class RoadmapRatingController {
 private final RoadmapRatingStore store;private final SpaceAuthorizationClient authority;private final RoadmapController browser;private final MeterRegistry metrics;private final String origin;
 RoadmapRatingController(RoadmapRatingStore store,SpaceAuthorizationClient authority,RoadmapController browser,MeterRegistry metrics,@Value("${brain.learning.browser-origin}")String origin){this.store=store;this.authority=authority;this.browser=browser;this.metrics=metrics;this.origin=origin;}
 private UUID authorize(UUID space,HttpServletRequest r,String action,boolean write,String parent){if(!r.isSecure())throw RoadmapGraph.bad();if(write&&(Collections.list(r.getHeaders("Origin")).size()!=1||!origin.equals(r.getHeader("Origin"))||r.getHeader("Sec-Fetch-Site")!=null&&!r.getHeader("Sec-Fetch-Site").equals("same-origin")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Same-origin request required");String token=null;if(r.getCookies()!=null)for(var c:r.getCookies())if(c.getName().equals("__Host-brain_guest")){if(token!=null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Duplicate credential");token=c.getValue();}return authority.authorize(space,token,action,"PUBLIC",parent);}
 private static long expected(HttpServletRequest r){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(h.size()!=1||!h.getFirst().matches("\"rr(0|[1-9][0-9]{0,18})\""))throw RoadmapGraph.bad();try{return Long.parseLong(h.getFirst().substring(3,h.getFirst().length()-1));}catch(NumberFormatException e){throw RoadmapGraph.bad();}}
 private ResponseEntity<?> mine(RoadmapRatingStore.Mine v){return ResponseEntity.ok().eTag("\"rr"+(v.rating()==null?0:v.rating().version())+"\"").cacheControl(CacheControl.noStore()).body(v);}
 private ResponseEntity<?> ok(Object v,String type){metrics.counter("brain.learning.ratings.reads","type",type).increment();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(v);}
 @GetMapping("/roadmap-rankings") ResponseEntity<?> ranking(@PathVariable String spaceId,HttpServletRequest r){RoadmapController.parameters(r,Set.of("sort","limit"));UUID space=RoadmapGraph.id(spaceId);String sort=Optional.ofNullable(r.getParameter("sort")).orElse("RATING");if(!Set.of("RATING","RATING_COUNT","RECENT").contains(sort))throw RoadmapGraph.bad();int limit=(int)RoadmapController.number(r.getParameter("limit"),20,100);authorize(space,r,"PUBLIC_ROADMAP_READ",false,RoadmapController.parent(r));return ok(store.ranking(space,sort,limit),"ranking");}
 @GetMapping("/roadmaps/{roadmapId}/ratings") ResponseEntity<?> summary(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);authorize(space,r,"PUBLIC_ROADMAP_READ",false,RoadmapController.parent(r));return ok(store.summary(space,id),"summary");}
 @GetMapping("/roadmaps/{roadmapId}/my-rating") ResponseEntity<?> get(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);UUID actor=authorize(space,r,"ROADMAP_RATING_READ",false,RoadmapController.parent(r));metrics.counter("brain.learning.ratings.reads","type","mine").increment();return mine(store.mine(space,id,actor));}
 @GetMapping("/roadmaps/{roadmapId}/my-rating/revisions") ResponseEntity<?> history(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r){RoadmapController.parameters(r,Set.of("before","limit"));var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);long before=RoadmapController.number(r.getParameter("before"),Long.MAX_VALUE,Long.MAX_VALUE);int limit=(int)RoadmapController.number(r.getParameter("limit"),5,10);UUID actor=authorize(space,r,"ROADMAP_RATING_READ",false,RoadmapController.parent(r));return ok(store.history(space,id,actor,before,limit),"history");}
 @PutMapping("/roadmaps/{roadmapId}/my-rating") ResponseEntity<?> put(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r)throws IOException{return change(spaceId,roadmapId,r,false);}
 @DeleteMapping("/roadmaps/{roadmapId}/my-rating") ResponseEntity<?> retire(@PathVariable String spaceId,@PathVariable String roadmapId,HttpServletRequest r)throws IOException{return change(spaceId,roadmapId,r,true);}
 private ResponseEntity<?> change(String spaceId,String roadmapId,HttpServletRequest r,boolean retire)throws IOException{RoadmapController.parameters(r,Set.of());var space=RoadmapGraph.id(spaceId);var id=RoadmapGraph.id(roadmapId);String parent=RoadmapController.parent(r);UUID actor=authorize(space,r,"ROADMAP_RATE",true,parent);long expected=expected(r),version=0;int score=0;if(retire){if(r.getContentLengthLong()>0||r.getHeader("Transfer-Encoding")!=null)throw RoadmapGraph.bad();}else{var v=browser.body(r,2048);if(v.size()!=2||!v.path("roadmapVersion").isIntegralNumber()||!v.path("roadmapVersion").canConvertToLong()||!v.path("score").isIntegralNumber()||!v.path("score").canConvertToInt())throw RoadmapGraph.bad();version=v.path("roadmapVersion").asLong();score=v.path("score").asInt();}var value=store.change(space,id,actor,expected,version,score,retire,parent.substring(3,35));metrics.counter("brain.learning.ratings.changes","type",retire?"retired":"saved").increment();org.slf4j.LoggerFactory.getLogger(getClass()).info("roadmap_rating_changed roadmap_id={} version={} trace_id={}",id,value.rating()==null?0:value.rating().version(),parent.substring(3,35));return mine(value);}
}
